/* Interactive pilot: all remote participants and service actions are simulated. */
Object.assign(state,{promptIndex:0,promptOpen:false,verified:false,blocked:false,notify:[],extended:false});
const prompts=[['Quale idea hai cambiato dopo una bella conversazione?','Di cosa vorresti si parlasse di più nella tua città?'],['Quale film vorresti poter rivedere per la prima volta?','Quale personaggio inviteresti a cena?'],['Quale canzone racconta questo periodo della tua vita?','Qual è il concerto che non hai dimenticato?'],['Quale sport ti ha insegnato qualcosa su di te?','Una vittoria che ricordi ancora?'],['Quale serie consiglieresti senza pensarci?','In quale universo narrativo passeresti un giorno?'],['Quale libro ti ha fatto cambiare prospettiva?','Quale luogo vorresti conoscere meglio?'],['Quale spettacolo ti ha lasciato senza parole?','Meglio un musical o un piccolo teatro?'],['Quale gioco vorresti riscoprire da zero?','Preferisci collaborare o sfidarti?']];
const pilotTopics=[0,1,2];
function available(i){return pilotTopics.includes(i)&&!state.blocked&&state.city.toLowerCase()==='roma'}
function promptCard(inCall=false){return `<div class="prompt-card"><span>Uno spunto, se vi va</span><p id="conversation-prompt">${prompts[state.category][state.promptIndex%2]}</p><button class="small-link" onclick="nextPrompt()">Un altro spunto ↗</button>${inCall?'<p class="microcopy">Spunto condiviso nella simulazione · nessun assistente in chiamata</p>':''}</div>`}
function nextPrompt(){state.promptIndex++;document.getElementById('conversation-prompt').textContent=prompts[state.category][state.promptIndex%2]}
function closePanel(){document.getElementById('filter-dialog').close()}
function panel(title,content){const d=document.getElementById('filter-dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-button" onclick="closePanel()" aria-label="Chiudi">${icon('close')}</button></div>${content}`;if(!d.open)d.showModal()}
function privacyPanel(){panel('Il controllo resta a te',`<div class="trust-list"><p><strong>Prima, solo la voce</strong>Nome, età, zona e interessi sono visibili. Foto e profilo completo si aprono solo dopo un sì reciproco. Nessuna anteprima a pagamento.</p><p><strong>Il tuo numero resta privato</strong>Il prodotto è pensato per chiamate in app, senza condividere numeri di telefono.</p><p><strong>Puoi cambiare idea</strong>Termina quando vuoi. La scelta dopo la chiamata è privata. Blocco e segnalazione restano accessibili.</p><p><strong>Questa è una demo</strong>Non acquisisce né trasmette audio, foto di verifica o numeri di telefono. Persone e conferme sono simulate; nessuna segnalazione viene inviata.</p></div>`)}
function safetyPanel(){panel('Sicurezza',`<p class="lead">Puoi interrompere la conversazione in qualsiasi momento.</p>${['call','extend','extendWaiting'].includes(state.view)?'<button class="secondary" onclick="closePanel();endCall()">Termina la conversazione</button>':''}<button class="secondary" onclick="blockPerson()">Blocca ${personName()}</button><button class="secondary" onclick="reportPanel()">Segnala un problema</button><button class="text-button" onclick="privacyPanel()">Privacy e regole</button><p class="microcopy">Azioni dimostrative, valide solo in questa sessione.</p>`)}
function blockPerson(){state.blocked=true;state.matched=false;state.messages=[];closePanel();go('home');toast('Profilo bloccato in questa sessione demo.')}
function reportPanel(){panel('Segnala un problema',`<form onsubmit="submitReport(event)"><label for="report-reason">Cosa è successo?</label><select id="report-reason" required><option value="">Scegli un motivo</option><option>Comportamento inappropriato</option><option>Profilo sospetto</option><option>Molestie o minacce</option><option>Altro</option></select><p class="microcopy">Non inserire dati personali. In questa demo non c’è un servizio di moderazione.</p><button class="primary" type="submit">Simula segnalazione e blocco</button></form>`)}
function submitReport(e){e.preventDefault();blockPerson();toast('Simulazione completata: profilo bloccato. Nessuna segnalazione inviata.')}
function verificationPanel(){panel('Verifica dell’account',`<div class="trust-list"><p><strong>1. Conferma il recapito</strong>Nel prodotto reale, un codice monouso confermerà il recapito.</p><p><strong>2. Conferma di essere tu</strong>È prevista una verifica fotografica con controlli contro l’uso di immagini altrui.</p><p><strong>3. Controlli continui</strong>La verifica non garantisce il comportamento di una persona. Blocco e segnalazione restano sempre disponibili.</p></div><p class="microcopy">Anteprima del percorso: non vengono raccolti documenti, selfie o recapiti.</p><button class="primary" onclick="state.verified=true;closePanel();render();toast('Percorso di verifica simulato')">Prova il completamento</button>`)}
function notifyTopic(){if(!state.notify.includes(state.category))state.notify.push(state.category);render();toast('Preferenza salvata nella sessione. Nessuna notifica reale attivata.')}
function pilotPanel(){panel('Un primo incontro, insieme',`<p class="lead">Ipotesi di lancio da testare</p><div class="trust-list"><p><strong>Roma · persone maggiorenni</strong>Un primo gruppo ristretto, interessato a conoscersi attraverso la voce. Le preferenze personali continuano a guidare gli incontri.</p><p><strong>Martedì e giovedì · 21–22</strong>Finestre proposte per concentrare le presenze. Orari di Roma; non sono eventi già organizzati.</p><p><strong>Politica e Sociale, Cinema e Musica</strong>Tre temi iniziali. Gli altri possono raccogliere interesse prima dell’apertura.</p></div><p class="microcopy">Nella demo puoi provare subito il percorso: disponibilità e attese sono simulate.</p>`)}
const previousRender=render;
render=function(){
 previousRender();
 if(state.view==='home'){
 app.innerHTML=`<section class="home editorial-home page-enter"><div class="home-heading"><div><p class="eyebrow">Ciao, ${esc(state.name)}</p><h1>Che conversazione<br>cerchi oggi?</h1></div><div class="voice-signature" aria-hidden="true"><span></span><span></span><span></span><span></span><span></span><span></span></div></div><div class="pilot-strip"><span><i></i>Il primo incontro dura 3 minuti</span><button onclick="pilotPanel()">Il pilota a Roma ${icon('chevron')}</button></div>${filters()}<div class="section-label"><h2>Da cosa cominciamo?</h2><span>Disponibilità demo</span></div><div class="category-grid">${categories.map((c,i)=>`<button class="category ${available(i)?'available':'later-topic'}" style="--room-color:${c.color};--card-order:${i}" onclick="selectCategory(${i})"><div class="category-top"><h3>${c.name}</h3>${icon('chevron')}</div>${art(i)}<div class="category-content"><p>${c.desc}</p><div class="category-footer"><span>${available(i)?`${c.n} compatibili · demo`:'Prossima finestra'}</span></div></div></button>`).join('')}</div><div class="home-trust"><span>${icon('lock')}Prima la voce. Il volto, se vi scegliete.</span><button class="small-link" onclick="privacyPanel()">Come ti proteggiamo ${icon('chevron')}</button></div></section>`;loadArt();
 }
 if(state.view==='category')app.innerHTML=`<section class="flow topic-view page-enter">${back()}<p class="eyebrow">Il vostro punto in comune</p><h1>${categories[state.category].name}</h1>${art(state.category,'large-art')}${promptCard()}<p class="availability-note">${available(state.category)?'Disponibilità simulata · attesa demo di pochi secondi':'Nessuna persona disponibile in questa simulazione'}</p><div class="flow-actions"><button class="primary" onclick="${available(state.category)?"go('ready')":"go('unavailable')"}">${available(state.category)?'Conosci qualcuno · 3 minuti':'Scopri la prossima finestra'}${icon('chevron')}</button><button class="text-button" onclick="openFilters()">${esc(state.preference)} · ${state.min}–${state.max} · ${esc(state.city)}</button></div></section>`;
 if(state.view==='ready')app.innerHTML=`<section class="flow ready page-enter">${back('category')}<p class="eyebrow">Un piccolo primo passo</p><h1>Hai qualche minuto<br>per conoscere qualcuno?</h1><div class="duration-seal"><strong>3</strong><span>minuti, per cominciare</span></div><div class="trust-list"><p><strong>Un posto tranquillo, e ci sei.</strong>Vi connettete solo quando entrambi siete pronti.</p><p><strong>Poi scegliete voi.</strong>Potete continuare insieme oppure salutarvi. Puoi uscire in ogni momento.</p></div><div class="flow-actions"><button class="primary" onclick="confirmReady()">Ci sono, cerca una persona ${icon('chevron')}</button><button class="text-button" onclick="go('home')">Magari più tardi</button></div><button class="small-link" onclick="privacyPanel()">Cosa può vedere di me?</button></section>`;
 if(state.view==='unavailable')app.innerHTML=`<section class="flow unavailable page-enter">${back('category')}<div class="empty-symbol">${icon('clock')}</div><p class="eyebrow">Il momento giusto conta</p><h1>Per ora, qui<br>è tranquillo.</h1><p class="lead">Nessuna persona compatibile disponibile.<br>Puoi provare un altro tema o lasciare un avviso.</p><div class="session-card"><span>Proposta per il pilota · Roma</span><h2>Martedì e giovedì</h2><p>21:00–22:00 · Politica e Sociale, Cinema e Musica</p><button class="small-link" onclick="pilotPanel()">Come funzionano le finestre</button></div><div class="flow-actions"><button class="primary" onclick="notifyTopic()" ${state.notify.includes(state.category)?'disabled':''}>${state.notify.includes(state.category)?'Avviso salvato nella demo':'Avvisami quando c’è qualcuno'}</button><button class="text-button" onclick="go('home')">Esplora un altro argomento</button></div><p class="microcopy">L’avviso resta solo in questa sessione. Nessuna notifica viene inviata.</p></section>`;
 if(state.view==='found'){
 app.querySelector('h1').innerHTML=`La prossima voce<br>è quella di ${personName()}.`;
 app.querySelector('.person-identity').insertAdjacentHTML('beforeend','<span class="verified-label">Account demo · verifica simulata</span>');
 app.querySelector('.flow-actions').innerHTML=`<div class="readiness"><span>${icon('check')}Tu ci sei</span><span id="peer-ready" aria-live="polite">${personName()} sta confermando…</span></div><button class="primary" id="connect-button" onclick="startCall()" disabled>${icon('phone')}Connettiti con ${personName()}</button><button class="text-button" onclick="startSearch()">Cerca ancora</button>`;
 app.querySelector('.footnote').insertAdjacentHTML('afterend','<button class="small-link" onclick="privacyPanel()">Numero privato · scelta reciproca</button>');
 }
 if(state.view==='call'){
 app.querySelector('.call-time').outerHTML=`<div class="call-clock"><span id="call-time">${formatTime(callSeconds)}</span><span>${state.extended?'Avete scelto di continuare':'Un primo incontro · 3 minuti'}</span></div>`;
 app.querySelector('.call-controls').insertAdjacentHTML('beforebegin',`<details class="call-prompt"><summary>Uno spunto per voi</summary>${promptCard(true)}</details>`);
 app.querySelector('.demo-note').insertAdjacentHTML('beforebegin','<button class="small-link safety-access" onclick="safetyPanel()">Sicurezza · blocca o segnala</button>');
 if(!state.extended)app.querySelector('.demo-note').insertAdjacentHTML('afterend','<button class="demo-skip" onclick="finishDemoRound()">Prova la fine dei 3 minuti</button>');
 }
 if(state.view==='extend')app.innerHTML=`<section class="flow extend page-enter"><p class="eyebrow">I primi tre minuti, insieme</p><h1>Vi va di<br>continuare?</h1><p class="lead">La conversazione riprende solo se lo scegliete entrambi. Va bene anche fermarsi qui.</p>${voiceStage()}<div class="flow-actions"><button class="primary" onclick="requestExtension()">Mi va di continuare</button><button class="text-button" onclick="endCall()">Concludi e scegli se risentirvi</button></div><button class="small-link" onclick="safetyPanel()">Sicurezza</button></section>`;
 if(state.view==='extendWaiting')app.innerHTML=`<section class="flow extend page-enter"><p class="eyebrow">La scelta è di entrambi</p><h1>Un momento per decidere.</h1><p class="lead" aria-live="polite">Aspettiamo la risposta di ${personName()}.</p>${voiceStage()}<button class="secondary" onclick="endCall()">Preferisco fermarmi qui</button><p class="microcopy">Conferma dell’altra persona simulata.</p></section>`;
 if(state.view==='profile')app.insertAdjacentHTML('beforeend',`<section class="account-trust"><h2>Il tuo spazio, protetto</h2><p>${state.verified?'Percorso di verifica completato nella demo.':'La verifica reale sarà necessaria per partecipare.'}</p><button class="secondary" onclick="verificationPanel()">${state.verified?'Rivedi la verifica demo':'Scopri la verifica dell’account'}</button><button class="text-button" onclick="privacyPanel()">Privacy e regole</button>${state.blocked?'<p>Un profilo bloccato nella sessione.</p>':''}</section>`);
 if(['person','chat'].includes(state.view))app.insertAdjacentHTML('beforeend','<button class="text-button" onclick="safetyPanel()">Blocca o segnala</button>');
 document.body.dataset.view=state.view;loadArt();nav();
};
const pilotNav=nav;
nav=function(){pilotNav();document.body.classList.toggle('no-bottom-nav',!['home','category','matches','messages','chat','person','profile'].includes(state.view));};
function confirmReady(){state.promptIndex=0;startSearch()}
startSearch=function(){if(!available(state.category)){go('unavailable');return}go('search');later(()=>{go('found');later(()=>{const p=document.getElementById('peer-ready'),b=document.getElementById('connect-button');if(p)p.innerHTML=icon('check')+personName()+' c’è · demo';if(b)b.disabled=false},1400)},2200)};
function runCallClock(){later(function tick(){if(state.view!=='call')return;callSeconds++;const t=document.getElementById('call-time');if(t)t.textContent=formatTime(callSeconds);if(callSeconds>=180&&!state.extended){go('extend');return}later(tick,1000)},1000)}
startCall=function(){state.muted=false;state.speaker=true;state.extended=false;callSeconds=0;go('call');runCallClock()};
function finishDemoRound(){callSeconds=Math.max(180,callSeconds);go('extend')}
function requestExtension(){go('extendWaiting');later(()=>{state.extended=true;go('call');runCallClock();toast('Avete scelto entrambi di continuare · simulazione')},1500)}
loadArt=function(){const files=['agora','cinema','musica','sport','anime','cultura','teatro','gaming'];document.querySelectorAll('[data-art]').forEach(el=>{el.style.backgroundImage=`url('assets/rooms/${files[Number(el.dataset.art)]}.png')`})};
render();
